package com.luci.pianoroom;
import java.util.*;
/** Deterministic notes + human listening ratings. Counters are not end-to-end latency. */
public class PianoBenchmark {
 public interface Driver {void buffer(int ms);void midi(int type,int key,int value);Metrics metrics();void finished(String report,int recommended);}
 public static final class Metrics {public double bufferMs,processMs,peak,limited,sampleMs,effectsMs,midiMs,inputMs;public int xruns,conflicts,late,hard,soft,voices,midiPending,midiOverflow;public String engine="AudioTrack";public long[] parallel=new long[10];public long[] perf=new long[33];public int rate;public boolean ready;public float invalid;public int[] channelVoices=new int[4];public boolean nativeAudio;public Metrics copy(){Metrics m=new Metrics();m.bufferMs=bufferMs;m.processMs=processMs;m.peak=peak;m.limited=limited;m.xruns=xruns;m.conflicts=conflicts;m.late=late;m.hard=hard;m.soft=soft;m.voices=voices;m.midiPending=midiPending;m.midiOverflow=midiOverflow;m.sampleMs=sampleMs;m.effectsMs=effectsMs;m.midiMs=midiMs;m.inputMs=inputMs;m.nativeAudio=nativeAudio;m.perf=perf.clone();m.engine=engine;m.parallel=parallel.clone();m.rate=rate;m.ready=ready;m.invalid=invalid;m.channelVoices=channelVoices.clone();return m;}}
 public static final class Result {public int requested,rating=-1;public double accepted,maxProcess,peak,limited,maxSample,maxEffects,maxMidi,maxInput;public int xruns,conflicts,late,hard,soft,maxVoices,midiPending,midiOverflow;}
 public final ArrayList<Result> results=new ArrayList<>();public boolean active,waiting;public int requested,recommended=-1;public String status="Pronto para testar três canais.";
 private final Driver driver;private final int[] plan;private final String context;private final int[] held=new int[128];private int index,tick;private long next,warmUntil;private Metrics start;private Result result;
 public PianoBenchmark(Driver d,int[] buffers,String context){driver=d;plan=buffers.clone();this.context=context;if(plan.length==0)throw new IllegalArgumentException("buffers");for(int n:plan)if(n<2||n>120)throw new IllegalArgumentException("buffer");}
 public void start(long now){active=true;index=0;begin(now);}
 private void begin(long now){waiting=false;requested=plan[index];driver.buffer(requested);tick=0;start=null;result=new Result();result.requested=requested;warmUntil=now+600;next=warmUntil;status="Preparando "+requested+" ms…";}
 private void note(int key,int velocity){held[key]++;driver.midi(0x90,key,velocity);}
 private void off(int key){if(held[key]>0){held[key]--;driver.midi(0x80,key,0);}}
 private void release(){for(int k=0;k<128;k++)while(held[k]>0)off(k);driver.midi(0xB0,64,0);}
 private void sample(){Metrics m=driver.metrics();if(!m.nativeAudio&&start.nativeAudio){cancel("A saída nativa mudou durante o teste.");return;}result.maxSample=Math.max(result.maxSample,m.sampleMs);result.maxEffects=Math.max(result.maxEffects,m.effectsMs);result.maxMidi=Math.max(result.maxMidi,m.midiMs);result.maxInput=Math.max(result.maxInput,m.inputMs);result.midiPending=Math.max(result.midiPending,m.midiPending);result.midiOverflow=Math.max(0,m.midiOverflow-start.midiOverflow);result.accepted=m.bufferMs;result.maxProcess=Math.max(result.maxProcess,m.processMs);result.peak=Math.max(result.peak,m.peak);result.limited=Math.max(result.limited,m.limited);result.maxVoices=Math.max(result.maxVoices,m.voices);result.xruns=Math.max(0,m.xruns-start.xruns);result.conflicts=Math.max(0,m.conflicts-start.conflicts);result.late=Math.max(0,m.late-start.late);result.hard=Math.max(0,m.hard-start.hard);result.soft=Math.max(0,m.soft-start.soft);}
 public void tick(long now){if(!active||waiting||now<next)return;if(start==null){start=driver.metrics().copy();result.maxProcess=0;next=now;}
  next=now+125; // no burst catch-up after a delayed UI/control tick
  int[] chord={48,55,60,64,67,72,76,79};
  if(tick==0||tick==32||tick==64)driver.midi(0xB0,64,127);
  if(tick<32){if(tick%8==0){int velocity=new int[]{35,75,120,95}[tick/8];for(int k:chord)note(k,velocity);}if(tick%8==4)for(int k:chord)off(k);}
  else if(tick<64){int[] arp={48,52,55,60,64,67,72,76};int k=arp[(tick-32)%8];note(k,30+(tick*19)%98);if(tick>32)off(arp[(tick-33)%8]);}
  else {if(tick%4==0)for(int k:chord)note(k,tick%8==0?127:45);if(tick%4==2)for(int k:chord)off(k);if(tick%2==0)note(60,50+(tick*11)%78);else off(60);}
  if(tick==31||tick==63||tick==87)release();
  if(tick%8==0){sample();if(!active)return;}status=requested+" ms solicitados · "+String.format(Locale.US,"%.1f",result.accepted)+" ms aceitos\n"+(tick<32?"Acordes: suave, médio e forte":tick<64?"Arpejos rápidos com pedal":"Acordes e repetições intensas")+" · "+Math.min(12,tick/8+1)+"/12 s\nFalhas "+result.xruns+" · conflitos "+result.conflicts+" · reciclagens "+result.hard+" · vozes máx. "+result.maxVoices;
  if(++tick>=96){release();sample();if(!active)return;results.add(result);waiting=true;status="Como soou em "+requested+" ms?\nAceito: "+String.format(Locale.US,"%.1f",result.accepted)+" ms · falhas "+result.xruns+" · conflitos "+result.conflicts+" · reciclagens "+result.hard;}
 }
 public void rate(int rating,long now){if(!active||!waiting||rating<0||rating>2)return;sample();if(!active)return;result.rating=rating;if(rating==0&&result.xruns==0&&result.conflicts==0&&result.late==0&&result.hard==0&&result.midiOverflow==0&&(recommended<0||requested<recommended))recommended=requested;if(++index>=plan.length){active=waiting=false;status="Teste concluído. Seus ajustes foram restaurados.";driver.finished(report(),recommended);}else begin(now);}
 public void cancel(String reason){if(!active)return;release();active=waiting=false;status="Teste interrompido: "+reason+" Seus ajustes foram restaurados.";driver.finished(report()+"\nInterrompido: "+reason,recommended);}
 public String report(){StringBuilder b=new StringBuilder("Piano Universe 0.27-preview1 · benchmark musical\n").append(context).append("\nTrês canais, faders de teste 28%, intensidades MIDI 30–127, acordes/arpejos/repetições/pedal; reverb híbrido, ressonância e chorus.\nNotas do teste são geradas dentro do app, sem trafegar pelo cabo MIDI. A saída de áudio selecionada participa do teste.\n12 s automáticos por buffer + avaliação manual na pausa; não mede o atraso total tecla→alto-falante.\n");for(Result r:results)b.append(String.format(Locale.US,"\nSolicitado %d ms / aceito %.2f ms / ouvido: %s\nFalhas %d / conflitos %d / fora do prazo %d / reciclagens %d / caudas suavizadas %d / vozes máx. %d\nProcessamento máximo observado %.3f ms / pico pré-proteção %.1f%% / amostras limitadas máx. %.1f%%\n",r.requested,r.accepted,r.rating==0?"Ótimo":r.rating==1?"Com estalos":r.rating==2?"Atraso perceptível":"Sem avaliação",r.xruns,r.conflicts,r.late,r.hard,r.soft,r.maxVoices,r.maxProcess,r.peak*100,r.limited)).append(String.format(Locale.US,"Picos por etapa amostrada: amostras %.3f ms / efeitos %.3f ms / eventos MIDI %.3f ms / entrada USB %.3f ms\nFila MIDI máx. %d / excessos no teste %d\n",r.maxSample,r.maxEffects,r.maxMidi,r.maxInput,r.midiPending,r.midiOverflow));return b.append(recommended>0?"\nMenor pedido avaliado Ótimo e sem falhas detectadas: "+recommended+" ms.":"\nNenhuma etapa reúne avaliação Ótimo e ausência de falhas detectadas.").append("\nEtapas são amostradas em 1 de cada 16 callbacks; seus máximos ocorrem em instantes diferentes e não devem ser somados.\nRecomendação vale para esta rota, bancos e carga; não garante estabilidade com outros bancos, temperatura ou gravação.").toString();}
}
